package dev.minecraftvideoplayer.web;
public final class AdminPage {
 private AdminPage(){}
 public static final String HTML="""<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Video Player Admin</title><style>body{font:14px system-ui;background:#0b0d12;color:#eee;max-width:900px;margin:auto;padding:20px}section{background:#151923;border:1px solid #303747;border-radius:12px;padding:16px;margin:12px 0}button,input{padding:10px;border-radius:8px;border:1px solid #394150;background:#0b0d12;color:#fff}button{cursor:pointer;margin:3px}pre{white-space:pre-wrap}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px}.card{padding:14px;background:#0f1219;border-radius:10px}</style></head><body><h1>Video Player Admin</h1><section><input id="token" type="password" placeholder="Admin token"><button onclick="save()">Connect</button><div class="grid"><div class="card">Web: <b id="web">-</b></div><div class="card">API keys: <b id="keys">-</b></div><div class="card">Port: <b id="port">-</b></div></div></section><section><h2>Server</h2><button onclick="rotate()">Rotate API key</button><button onclick="saveData()">Save library</button><button onclick="reloadCfg()">Reload config</button><pre id="msg"></pre></section><script>const $=x=>document.getElementById(x);function tok(){return localStorage.mvpAdminToken||$('token').value}async function call(p,o={}){let r=await fetch(p+'?token='+encodeURIComponent(tok()),o);if(!r.ok)throw Error(await r.text());return r.json()}async function load(){try{let x=await call('/api/admin/status');$('web').textContent=x.web;$('keys').textContent=x.youtubeKeys;$('port').textContent=x.port;$('msg').textContent='Connected.'}catch(e){$('msg').textContent='Error: '+e.message}}function save(){localStorage.mvpAdminToken=$('token').value;load()}async function rotate(){try{await call('/api/admin/rotate-key',{method:'POST'});load()}catch(e){$('msg').textContent=e.message}}async function saveData(){try{await call('/api/admin/save',{method:'POST'});$('msg').textContent='Data saved.'}catch(e){$('msg').textContent=e.message}}async function reloadCfg(){try{await call('/api/admin/reload',{method:'POST'});$('msg').textContent='Configuration reloaded.';load()}catch(e){$('msg').textContent=e.message}}$('token').value=localStorage.mvpAdminToken||'';load()</script></body></html>""";
}